62	/**
63	 * カードタッチで勤怠を記録
64	 * キオスク端末から呼び出される主要な関数
65	 */
66	export async function recordAttendance(cardId: string): Promise<{ 
67	  success: boolean; 
68	  message: string; 
69	  user: { display_name: string | null } | null; 
70	  type: 'in' | 'out' | null 
71	}> {
72	  const supabase = await createSupabaseAdminClient();
73	  
74	  const normalizedCardId = cardId.replace(/:/g, '').toLowerCase();
75	
76	  const { data: attendanceUser, error: attendanceUserError } = await supabase
77	    .schema('attendance')
78	    .from('users')
79	    .select('supabase_auth_user_id, card_id')
80	    .eq('card_id', normalizedCardId)
81	    .single();
82	
83	  if (attendanceUserError || !attendanceUser) {
84	    return { success: false, message: '未登録のカードです。', user: null, type: null };
85	  }
86	
87	  const userId = attendanceUser.supabase_auth_user_id;
88	  
89	  // member.members テーブルから Discord UID を取得
90	  const { data: memberData } = await supabase
91	    .schema('member')
92	    .from('members')
93	    .select('discord_uid')
94	    .eq('supabase_auth_user_id', userId)
95	    .single();
96	  
97	  let userDisplayName = '名無しさん';
98	  
99	  // Discord UIDがある場合、APIから本名を取得
100	  if (memberData?.discord_uid) {
101	    const { data: nickname } = await fetchMemberNickname(memberData.discord_uid);
102	    if (nickname) {
103	      userDisplayName = nickname;
104	    }
105	  }
106	
107	  const today = format(new Date(), 'yyyy-MM-dd');
108	  const now = new Date();
109	
110	  const { data: recentAttendances } = await supabase
111	    .schema('attendance')
112	    .from('attendances')
113	    .select('*')
114	    .eq('user_id', userId)
115	    .eq('date', today)
116	    .order('timestamp', { ascending: false })
117	    .limit(1);
118	
119	  let attendanceType: 'in' | 'out' = 'in';
120	  if (recentAttendances && recentAttendances.length > 0) {
121	    const lastType = recentAttendances[0].type;
122	    attendanceType = lastType === 'in' ? 'out' : 'in';
123	  }
124	
125	  const { error: insertError } = await supabase
126	    .schema('attendance')
127	    .from('attendances')
128	    .insert({
129	      user_id: userId,
130	      type: attendanceType,
131	      timestamp: now.toISOString(),
132	      date: today,
133	    });
134	
135	  if (insertError) {
136	    console.error('Error inserting attendance:', insertError);
137	    return { 
138	      success: false, 
139	      message: '勤怠記録に失敗しました。', 
140	      user: { display_name: userDisplayName }, 
141	      type: null 
142	    };
143	  }
144	
145	  const message = attendanceType === 'in' ? `${userDisplayName}さん、おはようございます!` : `${userDisplayName}さん、お疲れ様でした!`;
146	  
147	  revalidatePath('/dashboard');
148	  revalidatePath('/admin');
149	  
150	  return { 
151	    success: true, 
152	    message, 
153	    user: { display_name: userDisplayName }, 
154	    type: attendanceType 
155	  };
156	}
