410	/**
411	 * 月次勤怠データを取得（カレンダー表示用）
412	 */
413	export async function getMonthlyAttendance(userId: string, month: Date) {
414	  const supabase = await createSupabaseServerClient();
415	  const start = startOfMonth(month);
416	  const end = endOfMonth(month);
417	
418	  const { data, error } = await supabase
419	    .schema('attendance')
420	    .from('attendances')
421	    .select('date, type')
422	    .eq('user_id', userId)
423	    .gte('date', format(start, 'yyyy-MM-dd'))
424	    .lte('date', format(end, 'yyyy-MM-dd'))
425	    .order('timestamp', { ascending: true });
426	
427	  if (error) {
428	    console.error('Error fetching monthly attendance:', error);
429	    return [];
430	  }
431	
432	  const dailyStatus: Record<string, 'in' | 'out' | 'mixed'> = {};
433	  
434	  (data || []).forEach(att => {
435	    if (!att.date) return;
436	    dailyStatus[att.date] = att.type as 'in' | 'out';
437	  });
438	
439	  return Object.keys(dailyStatus).map(date => ({
440	    date,
441	    status: dailyStatus[date]
442	  }));
443	}
