3	import { generateCodeVerifier, generateCodeChallenge, generateState, buildAuthorizationUrl } from '@/lib/oauth/pkce';
4	import { cookies } from 'next/headers';
5	
6	export async function signInWithSTEM(): Promise<{ url: string }> {
7	  const oauthBaseUrl = (process.env.NEXT_PUBLIC_STEM_OAUTH_BASE_URL || 'http://localhost:3000/oauth').replace(/\/$/, '');
8	  const clientId = process.env.STEM_OAUTH_CLIENT_ID!;
9	  const appUrl = (process.env.NEXT_PUBLIC_APP_URL || 'http://localhost:3001').replace(/\/$/, '');
10	  const redirectUri = `${appUrl}/auth/oauth/callback`;
11	
12	  // PKCE パラメータを生成
13	  const codeVerifier = generateCodeVerifier();
14	  const codeChallenge = await generateCodeChallenge(codeVerifier);
15	  const state = generateState();
16	
17	  // Cookie に保存（OAuth コールバックで使用）
18	  const cookieStore = await cookies();
19	  cookieStore.set('oauth_code_verifier', codeVerifier, {
20	    httpOnly: true,
21	    secure: process.env.NODE_ENV === 'production',
22	    sameSite: 'lax',
23	    maxAge: 60 * 10,
24	    path: '/',
25	  });
26	  
27	  cookieStore.set('oauth_state', state, {
28	    httpOnly: true,
29	    secure: process.env.NODE_ENV === 'production',
30	    sameSite: 'lax',
31	    maxAge: 60 * 10,
32	    path: '/',
33	  });
34	
35	  // OAuth 認可URLを構築して返す
36	  const authUrl = buildAuthorizationUrl({
37	    authorizationEndpoint: `${oauthBaseUrl}/authorize`,
38	    clientId,
39	    redirectUri,
40	    codeChallenge,
41	    state,
42	  });
43	
44	  return { url: authUrl };
45	}
