38	/**
39	 * カードIDで本登録を完了
40	 */
41	export async function completeTempRegistration(token: string, cardId: string) {
42	    const supabase = await createSupabaseAdminClient();
43	
44	    try {
45	        // トークンの検証
46	        const { data: tempReg, error: tempRegError } = await supabase
47	            .schema('attendance')
48	            .from('temp_registrations')
49	            .select('*')
50	            .eq('token', token)
51	            .single();
52	
53	        if (tempRegError || !tempReg) {
54	            return { success: false, message: '無効なトークンです。' };
55	        }
56	
57	        if (tempReg.completed_at) {
58	            return { success: false, message: 'この登録は既に完了しています。' };
59	        }
60	
61	        // カードIDの重複チェック
62	        const normalizedCardId = cardId.toLowerCase().replace(/:/g, '');
63	        
64	        const { data: existingUser, error: checkError } = await supabase
65	            .schema('attendance')
66	            .from('users')
67	            .select('supabase_auth_user_id')
68	            .eq('card_id', normalizedCardId)
69	            .single();
70	
71	        if (existingUser) {
72	            return { success: false, message: 'このカードIDは既に使用されています。' };
73	        }
74	
75	        // attendance.usersにレコードを作成
76	        const { error: insertError } = await supabase
77	            .schema('attendance')
78	            .from('users')
79	            .insert({
80	                supabase_auth_user_id: tempReg.user_id,
81	                card_id: normalizedCardId,
82	            });
83	
84	        if (insertError) {
85	            console.error('Error inserting user:', insertError);
86	            return { success: false, message: 'ユーザー登録に失敗しました。' };
87	        }
88	
89	        // 仮登録を完了状態に
90	        const { error: updateError } = await supabase
91	            .schema('attendance')
92	            .from('temp_registrations')
93	            .update({ completed_at: new Date().toISOString() })
94	            .eq('token', token);
95	
96	        if (updateError) {
97	            console.error('Error updating temp registration:', updateError);
98	        }
99	
100	        return { success: true, message: '登録が完了しました！' };
101	    } catch (error) {
102	        console.error('Error in completeTempRegistration:', error);
103	        return { success: false, message: '予期しないエラーが発生しました。' };
104	    }
105	}
