200	/**
201	 * 全体統計を取得
202	 */
203	export async function getOverallStats(days: number = 30) {
204	    const supabase = await createSupabaseAdminClient();
205	    const today = new Date();
206	    const startDate = format(subDays(today, days - 1), 'yyyy-MM-dd');
207	    const endDate = format(today, 'yyyy-MM-dd');
208	
209	    try {
210	        // 総メンバー数
211	        const { count: totalMembers } = await supabase
212	            .schema('member')
213	            .from('members')
214	            .select('*', { count: 'exact', head: true })
215	            .is('deleted_at', null);
216	
217	        // 今日の出席者数
218	        const { data: attendanceUsers } = await supabase
219	            .schema('attendance')
220	            .from('users')
221	            .select('supabase_auth_user_id');
222	
223	        const attendanceUserIds = attendanceUsers?.map(u => u.supabase_auth_user_id) || [];
224	
225	        const { data: todayAttendanceData } = await supabase
226	            .schema('attendance')
227	            .from('attendances')
228	            .select('user_id', { count: 'exact' })
229	            .eq('type', 'in')
230	            .gte('timestamp', startOfDay(today).toISOString())
231	            .lte('timestamp', endOfDay(today).toISOString())
232	            .in('user_id', attendanceUserIds);
233	
234	        const uniqueTodayAttendees = todayAttendanceData 
235	            ? new Set(todayAttendanceData.map(d => d.user_id)).size 
236	            : 0;
237	
238	        // 過去N日間の活動日数
239	        const { data: activityDays } = await supabase
240	            .schema('attendance')
241	            .from('attendances')
242	            .select('date', { count: 'exact' })
243	            .gte('date', startDate)
244	            .lte('date', endDate);
245	
246	        const uniqueActivityDays = activityDays 
247	            ? new Set(activityDays.map(d => d.date)).size 
248	            : 0;
249	
250	        // 過去N日間の合計活動時間
251	        const { data: activityHours } = await supabase
252	            .schema('attendance')
253	            .from('attendances')
254	            .select('user_id, type, timestamp')
255	            .gte('timestamp', subDays(today, days - 1).toISOString())
256	            .order('user_id')
257	            .order('timestamp');
258	
259	        let totalHours = 0;
260	        if (activityHours) {
261	            const userSessions = new Map<string, Date[]>();
262	            activityHours.forEach((record: any) => {
263	                if (!userSessions.has(record.user_id)) {
264	                    userSessions.set(record.user_id, []);
265	                }
266	                userSessions.get(record.user_id)!.push(new Date(record.timestamp));
267	            });
268	
269	            userSessions.forEach(timestamps => {
270	                for (let i = 0; i < timestamps.length - 1; i += 2) {
271	                    const diff = timestamps[i + 1].getTime() - timestamps[i].getTime();
272	                    totalHours += diff / (1000 * 60 * 60);
273	                }
274	            });
275	        }
276	
277	        return {
278	            totalMembers: totalMembers || 0,
279	            todayAttendees: uniqueTodayAttendees,
280	            activityDays: uniqueActivityDays,
281	            totalHours: Math.round(totalHours * 10) / 10,
282	        };
283	    } catch (error) {
284	        console.error('Error in getOverallStats:', error);
285	        return {
286	            totalMembers: 0,
287	            todayAttendees: 0,
288	            activityDays: 0,
289	            totalHours: 0,
290	        };
291	    }
292	}
